// ── Descifrar Tokens AES-256-CBC ──────────────────────────────────
// La clave está guardada como credencial de n8n (NO hardcodeada).
// Configura en n8n → Settings → Credentials → Custom → ENCRYPTION_KEY
//
// Formato del token encriptado en DB: "<iv_hex>:<ciphertext_hex>"
// Mismo algoritmo que lib/crypto.ts del admin Next.js.

const crypto = require('crypto');

const ENCRYPTION_KEY = $env.TOKEN_ENCRYPTION_KEY; // 64-char hex string (32 bytes)
const ALGORITHM      = 'aes-256-cbc';

if (!ENCRYPTION_KEY || ENCRYPTION_KEY.length !== 64) {
  throw new Error('TOKEN_ENCRYPTION_KEY debe ser 64 caracteres hex. Configura la variable de entorno en n8n.');
}

function decryptToken(encrypted) {
  if (!encrypted) return null;
  const parts = encrypted.split(':');
  if (parts.length !== 2) {
    throw new Error(`Token inválido — esperado formato "<iv_hex>:<ciphertext_hex>", recibido: ${encrypted.substring(0, 20)}...`);
  }
  const [ivHex, ciphertextHex] = parts;
  const key      = Buffer.from(ENCRYPTION_KEY, 'hex');
  const iv       = Buffer.from(ivHex, 'hex');
  const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
  const decrypted = Buffer.concat([
    decipher.update(Buffer.from(ciphertextHex, 'hex')),
    decipher.final()
  ]);
  return decrypted.toString('utf8');
}

const tenant = $input.item.json;

// Descifrar cada token disponible
const fbToken = tenant.fb_token_encrypted ? decryptToken(tenant.fb_token_encrypted) : null;
const igToken = tenant.ig_token_encrypted ? decryptToken(tenant.ig_token_encrypted) : null;
const liToken = tenant.li_token_encrypted ? decryptToken(tenant.li_token_encrypted) : null;

return {
  json: {
    // Datos del tenant
    userId:             tenant.userId,
    userName:           tenant.userName,
    subscriptionStatus: tenant.subscriptionStatus,
    plan:               tenant.plan,
    // Tokens descifrados — NO loguear estos valores en producción
    fb_token:           fbToken,
    fb_page_id:         tenant.fb_page_id,
    ig_token:           igToken,
    ig_user_id:         tenant.ig_user_id,
    li_token:           liToken,
    li_person_id:       tenant.li_person_id,
  }
};
